import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname } from 'node:path';
import { z } from 'zod';
import { StonekeepError, errorMessage } from './errors.js';
import { categorySchema, formatZodError } from './rules.js';
import { compareStrings } from './text.js';
import type { DataMap, DataMapField } from './types.js';

const DATAMAP_COMMENT =
  'Generated by `stonekeep scan`. Commit this file and review changes in pull requests. ' +
  'Lists field identifiers only, never data values. Heuristic classification — not legal advice.';

const fieldSchema = z
  .object({
    id: z.string().min(1),
    entity: z.string().min(1),
    field: z.string().min(1),
    category: categorySchema,
    rule: z.string().min(1),
    confidence: z.number().min(0).max(1),
    source: z.enum(['sql', 'prisma', 'typeorm', 'json-schema', 'openapi']),
    location: z.object({ file: z.string(), line: z.number().int().nonnegative() }).strict(),
  })
  .strict();

const datamapSchema = z
  .object({
    $comment: z.string().optional(),
    version: z.literal(1),
    fields: z.array(fieldSchema),
  })
  .strict();

export function createDataMap(fields: readonly DataMapField[]): DataMap {
  return { version: 1, fields: [...fields].sort((a, b) => compareStrings(a.id, b.id)) };
}

/** Deterministic serialization (no timestamps) so diffs only show real changes. */
export function serializeDataMap(map: DataMap): string {
  const fields = map.fields.map((f) => ({
    id: f.id,
    entity: f.entity,
    field: f.field,
    category: f.category,
    rule: f.rule,
    confidence: f.confidence,
    source: f.source,
    location: { file: f.location.file, line: f.location.line },
  }));
  return `${JSON.stringify({ $comment: DATAMAP_COMMENT, version: map.version, fields }, null, 2)}\n`;
}

export function parseDataMap(json: unknown, source: string): DataMap {
  const parsed = datamapSchema.safeParse(json);
  if (!parsed.success) {
    throw new StonekeepError(
      'DATAMAP',
      `Invalid datamap ${source}:\n${formatZodError(parsed.error)}`,
    );
  }
  return { version: parsed.data.version, fields: parsed.data.fields };
}

export function readDataMap(path: string): DataMap {
  if (!existsSync(path)) {
    throw new StonekeepError(
      'DATAMAP',
      `Datamap not found: ${path}\nRun \`stonekeep scan\` and commit the generated file first.`,
    );
  }
  let json: unknown;
  try {
    json = JSON.parse(readFileSync(path, 'utf8'));
  } catch (error) {
    throw new StonekeepError('DATAMAP', `Cannot parse datamap ${path}: ${errorMessage(error)}`);
  }
  return parseDataMap(json, path);
}

export function writeDataMap(path: string, map: DataMap): void {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, serializeDataMap(map), 'utf8');
}
